//! compose-rs's foundation, as Compose's `androidx.compose.foundation`: the layouts (`Box`,
//! `Column`, `Row`, `Spacer`, in `layout`), `BasicText`, `BasicTextField` and shapes. The
//! foundation modifiers (`clickable`, `toggleable`, `background`, `border`, …) are methods of
//! `Modifier`, re-exported here (docs/06-ui.md).

#![forbid(unsafe_code)]
#![allow(non_snake_case)]

// Code generated by `#[composable]` names the runtime `::compose`.
extern crate compose_runtime as compose;

pub mod layout;
pub mod lazy;
mod scroll;
pub mod shape;
mod text;
mod text_field;

pub use compose_ui::{Alignment, Color, Modifier, RECTANGLE_SHAPE, Role, Shape, TextStyle};

/// A border's width and color, as Compose's `BorderStroke`.
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct BorderStroke {
    pub width: compose_ui::Dp,
    pub color: Color,
}

impl BorderStroke {
    pub const fn new(width: compose_ui::Dp, color: Color) -> BorderStroke {
        BorderStroke { width, color }
    }
}

impl compose_runtime::ComposeArg for BorderStroke {
    fn same(&self, other: &Self) -> bool {
        self == other
    }
}
pub use lazy::{LazyColumn, LazyListScope, LazyListState, LazyRow, remember_lazy_list_state};
pub use scroll::{ScrollModifiers, ScrollState, remember_scroll_state};
pub use shape::{
    CIRCLE_SHAPE, RoundedCornerShape, RoundedCornerShapeEach, RoundedCornerShapePercent,
};
pub use text::{BasicText, TextElement, TextNode};
pub use text_field::{BasicTextField, TextFieldElement, TextFieldNode, inner_text_field_only};
